CREATE TABLE billing_accounts(id text PRIMARY KEY,agency_id text REFERENCES agencies(id),client_id text REFERENCES clients(id),balance_cents bigint NOT NULL DEFAULT 0 CHECK(balance_cents>=0),held_cents bigint NOT NULL DEFAULT 0 CHECK(held_cents>=0 AND held_cents<=balance_cents),CHECK((agency_id IS NULL)<>(client_id IS NULL)));
CREATE TABLE billing_client_settings(client_id text PRIMARY KEY REFERENCES clients(id),direct boolean NOT NULL DEFAULT false,monthly_limit_cents bigint CHECK(monthly_limit_cents>=0));
CREATE TABLE billing_prices(id integer PRIMARY KEY CHECK(id=1),article_cents integer NOT NULL DEFAULT 0 CHECK(article_cents>=0),image_cents integer NOT NULL DEFAULT 0 CHECK(image_cents>=0),video_cents integer NOT NULL DEFAULT 0 CHECK(video_cents>=0),enabled boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1);
INSERT INTO billing_prices(id) VALUES(1);
CREATE TABLE billing_orders(id text PRIMARY KEY,account_id text NOT NULL REFERENCES billing_accounts(id),site_id text NOT NULL REFERENCES sites(id),client_id text NOT NULL REFERENCES clients(id),actor_id text NOT NULL REFERENCES users(id),request_key text NOT NULL,fingerprint text NOT NULL,amount_cents bigint NOT NULL CHECK(amount_cents>=0),price_snapshot jsonb NOT NULL,status text NOT NULL CHECK(status IN ('held','charged','released','review','refunded')),result jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,UNIQUE(site_id,request_key));
CREATE TABLE billing_ledger(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,account_id text NOT NULL REFERENCES billing_accounts(id),order_id text REFERENCES billing_orders(id),kind text NOT NULL CHECK(kind IN ('recharge','hold','charge','release','refund')),amount_cents bigint NOT NULL CHECK(amount_cents>=0),balance_cents bigint NOT NULL,held_cents bigint NOT NULL,actor text NOT NULL,note text NOT NULL,request_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,request_key));
CREATE INDEX billing_orders_client_month ON billing_orders(client_id,created_at,status);
CREATE INDEX billing_ledger_account ON billing_ledger(account_id,id DESC);
CREATE FUNCTION billing_ledger_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'billing ledger is append only'; END; $$;
CREATE TRIGGER billing_ledger_no_edit BEFORE UPDATE OR DELETE ON billing_ledger FOR EACH ROW EXECUTE FUNCTION billing_ledger_immutable();
